29	/// <summary>
30	/// The Edit-mode <b>HUD preview</b>: members of a SCREEN-SPACE scene layer
31	/// (<see cref="SceneLayerComponent.ScreenSpace"/> — the game's "HUD" grouping) are authored in
32	/// virtual-resolution coordinates on the HUD render pass, which is composited over the whole game
33	/// viewport — correct in Play, but in Edit the free view pans away while the HUD stays glued to the
34	/// pane, reading as chrome. This system re-projects them <b>into the CAMERA entity's frame</b>
35	/// while Paused: target flipped to Main, position mapped from virtual → the camera frustum's world
36	/// rect, text scale divided by the camera zoom — so the HUD text sits INSIDE the camera glyph,
37	/// exactly where the game will show it, and pans/zooms with the world like any authored content.
38	///
39	/// <para>Entering Play (or hiding the layer) restores the stashed authored values, so the REAL HUD
40	/// pass renders untouched — the plain game never composes this system at all. Weave after the
41	/// game's HUD-content systems (their frame's text lands before projection), before the draw prep.</para>
42	/// </summary>
43	public sealed class HudPreviewSystem : ISystem<GameState>
44	{
45	    private readonly ViewportManager _viewportManager;
46	    private readonly EntitySet _members;
47	    private readonly EntitySet _cameras;
48	
49	    public bool IsEnabled { get; set; } = true;
50	
51	    public HudPreviewSystem(World world, ViewportManager viewportManager)
52	    {
53	        if (world == null) throw new ArgumentNullException(nameof(world));
54	        _viewportManager = viewportManager ?? throw new ArgumentNullException(nameof(viewportManager));
55	        _members = world.GetEntities()
56	            .With<ChildOfComponent>()
57	            .With<DynamicTextComponent>()
58	            .With<TransformComponent>()
59	            .AsSet();
60	        _cameras = world.GetEntities()
61	            .With<CameraComponent>()
62	            .With<TransformComponent>()
63	            .AsSet();
64	    }
65	
66	    public void Update(GameState state)
67	    {
68	        if (!IsEnabled) return;
69	
70	        var hasCamera = TryGetCameraFrame(out var camCenter, out var zoom);
71	        var preview = state.RunMode == RunMode.Edit && hasCamera;
72	        var virtualSize = new Vector2(_viewportManager.VirtualWidth, _viewportManager.VirtualHeight);
73	
74	        foreach (var member in _members.GetEntities())
75	        {
76	            var layer = global::MonoDreams.System.Level.SceneLayerSystem.OwningLayer(member);
77	            var isHudMember = layer.IsAlive && layer.Get<SceneLayerComponent>().ScreenSpace;
78	
79	            if (!isHudMember || !preview)
80	            {
81	                Restore(member);
82	                continue;
83	            }
84	
85	            ref var text = ref member.Get<DynamicTextComponent>();
86	            ref var transform = ref member.Get<TransformComponent>();
87	
88	            // Stash the authored (virtual-space) values once; the projection below re-derives from
89	            // the stash every frame, so it never compounds.
90	            if (!member.Has<HudPreviewStashComponent>())
91	                member.Set(new HudPreviewStashComponent
92	                {
93	                    VirtualPosition = transform.Position,
94	                    TextScale = text.Scale,
95	                    Target = text.Target,
96	                });
97	            var stash = member.Get<HudPreviewStashComponent>();
98	
99	            if (!layer.Get<SceneLayerComponent>().Visible)
100	            {
101	                // The eye toggle hides the preview (the game's own pass honors it on the next
102	                // restore only in Edit — Play HUD visibility is gameplay's business).
103	                transform.Position = SystemsPanelLayout.ParkedPosition;
104	                member.NotifyChanged<TransformComponent>();
105	                continue;
106	            }
107	
108	            // Virtual → the camera frame's world rect: the frustum covers virtual/zoom world units
109	            // centred on the camera entity; text glyphs shrink by the same factor.
110	            var topLeft = camCenter - virtualSize / (2f * zoom);
111	            text.Target = RenderTargetID.Main;
112	            text.Scale = stash.TextScale / zoom;
113	            transform.Position = topLeft + stash.VirtualPosition / zoom;
114	            member.NotifyChanged<TransformComponent>();
115	        }
116	    }
117	
118	    /// <summary>Restores a member's authored HUD-space values and drops the stash (idempotent).</summary>
119	    private static void Restore(in Entity member)
120	    {
121	        if (!member.Has<HudPreviewStashComponent>()) return;
122	        var stash = member.Get<HudPreviewStashComponent>();
123	        ref var text = ref member.Get<DynamicTextComponent>();
124	        ref var transform = ref member.Get<TransformComponent>();
125	        text.Target = stash.Target;
126	        text.Scale = stash.TextScale;
127	        transform.Position = stash.VirtualPosition;
128	        member.NotifyChanged<TransformComponent>();
129	        member.Remove<HudPreviewStashComponent>();
130	    }
131	
132	    /// <summary>The scene camera entity's frame: world centre + zoom. False when no camera exists
133	    /// (a bare world) — the preview then leaves the HUD in its authored pass.</summary>
134	    private bool TryGetCameraFrame(out Vector2 center, out float zoom)
135	    {
136	        foreach (var cam in _cameras.GetEntities())
137	        {
138	            center = cam.Get<TransformComponent>().WorldPosition;
139	            zoom = MathF.Max(0.05f, cam.Get<CameraComponent>().Zoom);
140	            return true;
141	        }
142	        center = Vector2.Zero;
143	        zoom = 1f;
144	        return false;
145	    }
