1	using System.Collections.Generic;
2	using DefaultEcs;
3	using DefaultEcs.System;
4	using Microsoft.Xna.Framework;
5	using Microsoft.Xna.Framework.Graphics;
6	using MonoDreams.Component;
7	using MonoDreams.Component.Draw;
8	using MonoDreams.State;
9	
10	namespace MonoDreams.UI;
11	
12	/// <summary>
13	/// Prepares DrawComponents with mesh data for button outlines.
14	/// This system is game-agnostic and generates generic vertex buffer data.
15	/// </summary>
16	[With(typeof(SimpleButtonComponent), typeof(TransformComponent))]
17	public class ButtonMeshPrepSystem(World world) : AEntitySetSystem<GameState>(world)
18	{
19	    protected override void Update(GameState state, in Entity entity)
20	    {
21	        ref readonly var outline = ref entity.Get<SimpleButtonComponent>();
22	        ref readonly var transform = ref entity.Get<TransformComponent>();
23	
24	        var vertices = new List<VertexPositionColor>();
25	        var indices = new List<int>();
26	        var indexOffset = 0;
27	
28	        // Calculate corners of the button using world position as top-left origin
29	        // (Layout system positions elements at their top-left corner)
30	        var position = transform.WorldPosition;
31	
32	        // Optional visual-only "pop" scale around the button's centre (ButtonVisualSystem drives
33	        // it on press). Zero means "unset" → full size. The hit-test still uses the unscaled Size,
34	        // so the geometry stays anchored while the drawn quad scales.
35	        var visualScale = outline.VisualScale <= 0f ? 1f : outline.VisualScale;
36	        var center = position + outline.Size * 0.5f;
37	        Vector2 Scaled(Vector2 corner) => center + (corner - center) * visualScale;
38	
39	        // Top-left, top-right, bottom-right, bottom-left corners
40	        var topLeft = Scaled(position);
41	        var topRight = Scaled(new Vector2(position.X + outline.Size.X, position.Y));
42	        var bottomRight = Scaled(position + outline.Size);
43	        var bottomLeft = Scaled(new Vector2(position.X, position.Y + outline.Size.Y));
44	
45	        // Optional solid fill behind the outline.
46	        if (outline.FillColor.A > 0)
47	        {
48	            var fill = outline.FillColor;
49	            vertices.Add(new VertexPositionColor(new Vector3(topLeft, 0), fill));
50	            vertices.Add(new VertexPositionColor(new Vector3(topRight, 0), fill));
51	            vertices.Add(new VertexPositionColor(new Vector3(bottomRight, 0), fill));
52	            vertices.Add(new VertexPositionColor(new Vector3(bottomLeft, 0), fill));
53	            indices.Add(indexOffset);
54	            indices.Add(indexOffset + 1);
55	            indices.Add(indexOffset + 2);
56	            indices.Add(indexOffset);
57	            indices.Add(indexOffset + 2);
58	            indices.Add(indexOffset + 3);
59	            indexOffset += 4;
60	        }
61	
62	        // Create thick lines for the four sides of the rectangle (skip if thickness is zero).
63	        if (outline.LineThickness > 0f)
64	        {
65	            AddThickLine(vertices, indices, topLeft, topRight, outline.LineThickness, outline.Color, ref indexOffset);
66	            AddThickLine(vertices, indices, topRight, bottomRight, outline.LineThickness, outline.Color, ref indexOffset);
67	            AddThickLine(vertices, indices, bottomRight, bottomLeft, outline.LineThickness, outline.Color, ref indexOffset);
68	            AddThickLine(vertices, indices, bottomLeft, topLeft, outline.LineThickness, outline.Color, ref indexOffset);
69	        }
70	
71	        // The button's draw depth: honor SimpleButtonComponent.LayerDepth, treating 0 (unset) as the
72	        // default 0.95. Setting it lower lets a screen push the fill/ring behind sibling decorations
73	        // (e.g. a checkbox box + checkmark) so the depth ordering stays strict.
74	        var layerDepth = outline.LayerDepth > 0f ? outline.LayerDepth : 0.95f;
75	
76	        // Set or update the DrawComponent.
77	        // Vertices above are baked in world coordinates, so WorldMatrix must be
78	        // identity (or null). When the screen also runs MeshPrepSystem (which would
79	        // otherwise write transform.WorldMatrix here) place this system AFTER
80	        // MeshPrepSystem in the draw pipeline so this assignment wins.
81	        if (!entity.Has<DrawComponent>())
82	        {
83	            entity.Set(new DrawComponent
84	            {
85	                Type = DrawElementType.Mesh,
86	                Vertices = vertices.ToArray(),
87	                Indices = indices.ToArray(),
88	                PrimitiveType = PrimitiveType.TriangleList,
89	                Target = outline.Target,
90	                LayerDepth = layerDepth,
91	                WorldMatrix = Matrix.Identity,
92	            });
93	        }
94	        else
95	        {
96	            ref var drawComponent = ref entity.Get<DrawComponent>();
97	            drawComponent.Type = DrawElementType.Mesh;
98	            drawComponent.Vertices = vertices.ToArray();
99	            drawComponent.Indices = indices.ToArray();
100	            drawComponent.PrimitiveType = PrimitiveType.TriangleList;
101	            drawComponent.Target = outline.Target;
102	            drawComponent.LayerDepth = layerDepth;
103	            drawComponent.WorldMatrix = Matrix.Identity;
104	        }
105	    }
106	
107	    private void AddThickLine(List<VertexPositionColor> vertices, List<int> indices,
108	        Vector2 start, Vector2 end, float thickness, Color color, ref int indexOffset)
109	    {
110	        // Calculate direction and perpendicular vector for thickness
111	        Vector2 direction = end - start;
112	        Vector2 perpendicular = new Vector2(-direction.Y, direction.X);
113	        perpendicular.Normalize();
114	        perpendicular *= thickness / 2;
115	
116	        // Create the four corners of the line segment
117	        vertices.Add(new VertexPositionColor(new Vector3(start + perpendicular, 0), color));
118	        vertices.Add(new VertexPositionColor(new Vector3(start - perpendicular, 0), color));
119	        vertices.Add(new VertexPositionColor(new Vector3(end - perpendicular, 0), color));
120	        vertices.Add(new VertexPositionColor(new Vector3(end + perpendicular, 0), color));
121	
122	        // Create two triangles to form the line
123	        indices.Add(indexOffset);
124	        indices.Add(indexOffset + 1);
125	        indices.Add(indexOffset + 2);
126	
127	        indices.Add(indexOffset);
128	        indices.Add(indexOffset + 2);
129	        indices.Add(indexOffset + 3);
130	
131	        indexOffset += 4;
132	    }
133	}
